const links = phi.query("a", { fields: ["href"], limit: 300 });
const items = links.items.map(l => ((l.text||"").replace(/\s+/g," ").trim()) + " || " + (l.href||""));
const feis = items.filter(s => /FEIS|Final Env|DSEIS|Supplemental Environmental|Environmental Management Plan|Older project/i.test(s));
// also grab the HTML around the Documents section
const html = phi.js(() => {
  const heads = [...document.querySelectorAll("h1,h2,h3,h4,h5,strong,p,div")].filter(e => /^Documents$/i.test((e.textContent||"").trim()));
  if (!heads.length) return null;
  const h = heads[heads.length-1];
  const cont = h.closest("section,div") || h.parentElement;
  return cont ? cont.innerHTML.slice(0, 4000) : null;
});
return { feis, html };

